// Validate the ticket and run the safety net (keywords that always mean P1).
const ticket = $('Webhook: new ticket').first().json.body || {};
if (!ticket.ticket_id) throw new Error('missing ticket_id');
if (!String(ticket.body || '').trim()) throw new Error('missing ticket body');

const SAFETY_PATTERNS = ["allerg", "swelling", "hospital", "bleed", "chemical burn", "poison", "brûlure", "saigne", "حساسية", "مستشفى", "شربت", "حرق", "hacked", "اختراق", "fraud", "احتيال", "lawyer", "legal action", "حماية المستهلك", "other customers'? (names|data)"];
const text = `${ticket.subject || ''}\n${ticket.body}`;
let safetyKeyword = '';
for (const pattern of SAFETY_PATTERNS) {
  const match = text.match(new RegExp(pattern, 'i'));
  if (match) { safetyKeyword = match[0]; break; }
}
return [{
  json: { ticket_id: String(ticket.ticket_id), ticket, safety_keyword: safetyKeyword, dedupe_text: `${ticket.run_tag || ''}|${ticket.ticket_id}` },
}];

// Idempotency: the same input twice must not create two records.
// Keys live in this workflow's static data (n8n saves it after production runs, not manual test runs).
const item = $input.first().json;
const key = item.dedupe_key || item.dedupe_text;
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const duplicate = Boolean(store.seen[key]);
if (!duplicate) store.seen[key] = new Date().toISOString();
const json = { ...item, dedupe_key: key, is_duplicate: duplicate };
const binary = undefined; // invoices carry the uploaded file along
return [binary ? { json, binary } : { json }];

// Build the OpenAI-compatible request. The ticket goes in the user message as JSON data.
const cfg = $('Config').first().json;
const item = $input.first().json;
const t = item.ticket;
const user = JSON.stringify({ ticket_id: t.ticket_id, channel: t.channel || '', customer_tier: t.customer_tier || '', subject: t.subject || '', body: t.body });
return [{
  json: {
    ...item,
    step: 'ai_triage',
    llm_request: {
      model: cfg.model_cheap,
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [{ role: 'system', content: cfg.prompt_triage }, { role: 'user', content: user }],
    },
  },
}];

// JSON-schema check of the model's reply. Invalid output is never used: it goes to human review.
// Parse the model's reply and check it against a JSON Schema (the subset our schemas use).
function parseJsonObject(text) {
  if (!text) return null;
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try {
    const value = JSON.parse(text.slice(start, end + 1));
    return value && typeof value === 'object' && !Array.isArray(value) ? value : null;
  } catch (error) {
    return null;
  }
}
function isType(value, type) {
  if (type === 'null') return value === null;
  if (type === 'number') return typeof value === 'number' && Number.isFinite(value);
  if (type === 'integer') return Number.isInteger(value);
  if (type === 'object') return value !== null && typeof value === 'object' && !Array.isArray(value);
  if (type === 'array') return Array.isArray(value);
  return typeof value === type;
}
function schemaErrors(value, schema, path = '$') {
  if (value === null && path === '$') return ['output is not a JSON object'];
  const types = [].concat(schema.type || []);
  if (types.length && !types.some((type) => isType(value, type))) return [`${path}: expected ${types.join(' or ')}`];
  const errors = [];
  if (schema.enum && !schema.enum.includes(value)) errors.push(`${path}: must be one of ${JSON.stringify(schema.enum)}`);
  if (typeof value === 'number') {
    if (schema.minimum !== undefined && value < schema.minimum) errors.push(`${path}: below ${schema.minimum}`);
    if (schema.maximum !== undefined && value > schema.maximum) errors.push(`${path}: above ${schema.maximum}`);
  }
  if (typeof value === 'string') {
    if (schema.maxLength !== undefined && value.length > schema.maxLength) errors.push(`${path}: longer than ${schema.maxLength}`);
    if (schema.pattern && !new RegExp(schema.pattern).test(value)) errors.push(`${path}: does not match ${schema.pattern}`);
  }
  if (isType(value, 'object')) {
    const properties = schema.properties || {};
    for (const key of schema.required || []) if (!(key in value)) errors.push(`${path}.${key}: missing`);
    for (const [key, sub] of Object.entries(properties)) if (key in value) errors.push(...schemaErrors(value[key], sub, `${path}.${key}`));
    if (schema.additionalProperties === false) {
      for (const key of Object.keys(value)) if (!(key in properties)) errors.push(`${path}.${key}: not allowed`);
    }
  }
  return errors;
}
const SCHEMA = {"$schema": "https://json-schema.org/draft/2020-12/schema", "title": "Ticket triage", "type": "object", "required": ["priority", "sentiment", "team", "summary", "confidence"], "additionalProperties": false, "properties": {"priority": {"type": "string", "enum": ["P1", "P2", "P3", "P4"]}, "sentiment": {"type": "string", "enum": ["positive", "neutral", "negative"]}, "team": {"type": "string", "enum": ["Technical", "Billing", "Delivery", "Product", "Account"]}, "summary": {"type": "string", "maxLength": 240}, "confidence": {"type": "number", "minimum": 0, "maximum": 1}}};
const { llm_request, ...context } = $('Build AI request').first().json;
const content = $input.first().json.choices?.[0]?.message?.content || '';
const ai = parseJsonObject(content);
const errors = schemaErrors(ai, SCHEMA);
return [{ json: { ...context, ai: errors.length ? null : ai, schema_errors: errors } }];

// Code decides the final priority and whether to escalate.
// This node is reached two ways: normally (after the schema check) or, when the AI call failed,
// through "Safety case?" so that a safety ticket is escalated even while the model is down.
// CSV helpers: one line per record, quoted only when needed (same rule as Python's csv module).
function csvCell(value) {
  if (value === null || value === undefined) return '';
  const text = typeof value === 'object' ? JSON.stringify(value) : String(value);
  return /[",\n\r]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
}
function csvRow(columns, record) {
  return columns.map((column) => csvCell(record[column])).join(',') + '\n';
}
const ERROR_COLUMNS = ["timestamp", "workflow", "item_id", "step", "error_type", "message"];
const cfg = $('Config').first().json;
const checked = $('Check input').first().json;
const incoming = $input.first().json;
const aiFailed = Boolean(incoming.error);
const ai = aiFailed ? null : incoming.ai;
const subject = checked.ticket.subject || '';

function applyRules(ai, safetyKeyword, threshold) {
  const fields = ai ? { priority: ai.priority, team: ai.team, sentiment: ai.sentiment, summary: ai.summary } : null;
  if (safetyKeyword) {
    return { status: 'escalated', priority: 'P1', team: ai ? ai.team : 'Product', sentiment: ai ? ai.sentiment : 'negative',
             summary: ai ? ai.summary : subject, reason: `safety net matched '${safetyKeyword}'`, escalate: true };
  }
  if (ai === null) {
    return { status: 'needs_review', priority: '', team: 'Triage queue', sentiment: '', summary: subject,
             reason: 'AI output failed the JSON schema check', escalate: false };
  }
  if (ai.priority === 'P1') return { ...fields, status: 'escalated', reason: 'AI set P1', escalate: true };
  if (ai.confidence < threshold) return { ...fields, status: 'needs_review', reason: 'low confidence', escalate: false };
  return { ...fields, status: 'routed', reason: '', escalate: false };
}

const result = { ticket_id: checked.ticket_id, ...applyRules(ai, checked.safety_keyword, Number(cfg.confidence_threshold)) };
let errorLine = '';
if (aiFailed) {
  // Log the failure and forget the key so the ticket can be re-run once the model is back.
  const error = incoming.error;
  const record = { timestamp: new Date().toISOString(), workflow: 'ticket_triage', item_id: checked.ticket_id, step: 'ai_triage',
                   error_type: error.name || 'Error', message: String(error.description || error.message || error).slice(0, 500) };
  errorLine = csvRow(ERROR_COLUMNS, record);
  const store = $getWorkflowStaticData('global');
  if (store.seen) delete store.seen[checked.dedupe_text];
}
return [{ json: { ...result, schema_errors: incoming.schema_errors || [], error_line: errorLine } }];

// P1: alert the on-call person immediately (mock: a line in outputs/escalations.csv).
// CSV helpers: one line per record, quoted only when needed (same rule as Python's csv module).
function csvCell(value) {
  if (value === null || value === undefined) return '';
  const text = typeof value === 'object' ? JSON.stringify(value) : String(value);
  return /[",\n\r]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
}
function csvRow(columns, record) {
  return columns.map((column) => csvCell(record[column])).join(',') + '\n';
}
const COLUMNS = ["timestamp", "ticket_id", "priority", "team", "message"];
const cfg = $('Config').first().json;
const r = $input.first().json;
const record = {
  timestamp: new Date().toISOString(), ticket_id: r.ticket_id, priority: 'P1', team: r.team,
  message: `@on-call P1 ticket ${r.ticket_id} for ${r.team}: ${r.summary}`,
};
return [{ json: { target_path: `${cfg.base_dir}/outputs/escalations.csv`, line: csvRow(COLUMNS, record) } }];

// Post every ticket to the team channel (mock: outputs/channel_posts.csv),
// queue it for a person if needed, and log the AI error if there was one.
// CSV helpers: one line per record, quoted only when needed (same rule as Python's csv module).
function csvCell(value) {
  if (value === null || value === undefined) return '';
  const text = typeof value === 'object' ? JSON.stringify(value) : String(value);
  return /[",\n\r]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
}
function csvRow(columns, record) {
  return columns.map((column) => csvCell(record[column])).join(',') + '\n';
}
const CHANNEL_COLUMNS = ["timestamp", "ticket_id", "status", "priority", "team", "sentiment", "summary", "reason"];
const REVIEW_COLUMNS = ["timestamp", "workflow", "item_id", "reason", "details"];
const cfg = $('Config').first().json;
const r = $('Apply rules').first().json;
const now = new Date().toISOString();
const rows = [{ target_path: `${cfg.base_dir}/outputs/channel_posts.csv`, line: csvRow(CHANNEL_COLUMNS, { ...r, timestamp: now }) }];
if (r.status === 'needs_review') {
  const review = { timestamp: now, workflow: 'ticket_triage', item_id: r.ticket_id, reason: r.reason, details: { schema_errors: r.schema_errors } };
  rows.push({ target_path: `${cfg.base_dir}/outputs/human_review_queue.csv`, line: csvRow(REVIEW_COLUMNS, review) });
}
if (r.error_line) rows.push({ target_path: `${cfg.base_dir}/logs/errors.csv`, line: r.error_line });
const response = { ticket_id: r.ticket_id, status: r.status, priority: r.priority, team: r.team, sentiment: r.sentiment,
                   summary: r.summary, reason: r.reason, escalated: r.escalate };
return rows.map((row) => ({ json: { ...row, response } }));

// Error branch: write one row to logs/errors.csv, forget the idempotency key so the input
// can be retried later, and answer the webhook caller with status "error".
// CSV helpers: one line per record, quoted only when needed (same rule as Python's csv module).
function csvCell(value) {
  if (value === null || value === undefined) return '';
  const text = typeof value === 'object' ? JSON.stringify(value) : String(value);
  return /[",\n\r]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
}
function csvRow(columns, record) {
  return columns.map((column) => csvCell(record[column])).join(',') + '\n';
}
const COLUMNS = ["timestamp", "workflow", "item_id", "step", "error_type", "message"];
const cfg = $('Config').first().json;
const item = $input.first().json;
const error = item.error || 'unknown error';
const message = typeof error === 'string' ? error : error.description || error.message || JSON.stringify(error);
let itemId = 'unknown';
try {
  itemId = $('Webhook: new ticket').first().json.body.ticket_id || itemId; // straight from the trigger, in case the input check failed
} catch (noTrigger) {
  // started by the schedule, or no such field
}
try {
  const checked = $('Seen before?').first().json;
  itemId = checked.ticket_id || itemId;
  const key = checked.dedupe_key || checked.dedupe_text;
  const store = $getWorkflowStaticData('global');
  if (key && store.seen) delete store.seen[key];
} catch (notExecuted) {
  // the input check itself failed, so no key was stored yet
}
const record = {
  timestamp: new Date().toISOString(),
  workflow: 'ticket_triage',
  item_id: itemId,
  step: item.step || 'check_input',
  error_type: typeof error === 'string' ? 'Error' : error.name || 'Error',
  message: String(message).slice(0, 500),
};
return [{
  json: {
    target_path: `${cfg.base_dir}/logs/errors.csv`,
    line: csvRow(COLUMNS, record),
    response: { status: 'error', item_id: itemId, step: record.step, reason: record.message },
  },
}];
